//clean up and bail helper used for SHT-derived size calculation
#define CLEANUP_FAIL() do { \
    if (sect_header_entries) { \
        for (int k = 0; k < adjusted_numEntries; ++k) free(sect_header_entries[k]); \
        free(sect_header_entries); \
    } \
    *filtered_numEntries = 0; \
    return NULL; \
} while(0)


