/*************************************************************/
/* Structs for block-level section validation                */
/*************************************************************/

// Note: everything in this section is currently unused. 
// Since cross-validation logic can drive up memory while offering limited benefits

// Instead, coverage stats are currently the main driver


/************************************************************
 * ValidateResult
 * - Role: tri-state validation outcome for cross-validation checks:
 *     FAIL = definite invalid, INCONCLUSIVE = can't decide, PASS = validated.
 *     Used as return value for the main cross-validation functions. 
 * 
 * - Why: lets scoring penalize real contradictions without penalizing
 *   missing-metadata cases.
 * 
 * - Persistence: return-by-value / local; not stored per-block long-term.
 * - Memory: LOW (typically 4 bytes).
 ************************************************************/
typedef enum {
    VR_FAIL = 0,         /* definitively invalid (structural or anchor-backed failure) */
    VR_INCONCLUSIVE = 1, /* could not validate or invalidate (missing anchors) */
    VR_PASS = 2          /* validated with required anchors (e.g., PHT) */
} ValidateResult;


/************************************************************
 * Summarizes the best contiguous run of valid symbol
 * entries found inside a component slice (best alignment),
 * preferring runs that encounter DT_NULL.
 * 
 * Provides cheap “structure evidence” that bytes look like a
 * real .dynamic table. 
 * 
 * In memory: Non-persistent; returned by value / used as a local stack
 * object. Owns no heap memory. Memory cost is relatively low compared to 
 * block / file state 
 ************************************************************/
typedef struct {
    ValidateResult result; /* PASS / INCONCLUSIVE / FAIL */
    bool           is_rela; /* chosen flavor when a run is found */
    uint64_t       start;   /* byte offset (within component slice) of first entry */
    uint64_t       count;   /* number of consecutive validated entries */
    uint64_t       entry_size; /* size of each entry for chosen flavor */
    bool           used_segments; /* true iff PT_LOAD containment was enforced */
    bool           used_machine;  /* true iff psABI type allowlist was applied */
    uint64_t span_bytes; /* how big the validated span is */
} RelocScanResult;


/************************************************************
 * Summarizes the best contiguous run of valid relocation
 * entries found inside a component slice (best alignment),
 * preferring runs that encounter DT_NULL.
 * 
 * Provides cheap “structure evidence” that bytes look like a
 * real .dynamic table. 
 * 
 * In memory: Non-persistent; returned by value / used as a local stack
 * object. Owns no heap memory. Memory cost is relatively low compared to 
 * block / file state 
 ************************************************************/
typedef struct {
    ValidateResult result;  /* VR_FAIL / VR_INCONCLUSIVE / VR_PASS */
    uint64_t start;           /* byte-alignment offset within slice */
    uint64_t count;           /* number of consecutive entries */
    uint64_t entry_size;      /* sizeof(Elf{32,64}_Sym) */
    bool     used_segments;   /* true if PT_LOAD containment enforced */
    uint64_t span_bytes; /* how big the validated span is */
} SymbolScanResult;


/************************************************************
 * Summarizes the best contiguous run of valid Elf{32,64}_Dyn
 * entries found inside a component slice (best alignment),
 * preferring runs that encounter DT_NULL.
 * 
 * Provides cheap “structure evidence” that bytes look like a
 * real .dynamic table. 
 * 
 * In memory: Non-persistent; returned by value / used as a local stack
 * object. Owns no heap memory. Memory cost is relatively low compared to 
 * block / file state 
 ************************************************************/
typedef struct {
    uint64_t start;       /* offset (within component slice) where the run starts */
    uint64_t count;       /* number of consecutive entries */
    uint64_t entry_size;  /* sizeof(ElfXX_Dyn) actually used */
    bool     saw_dt_null; /* whether a DT_NULL was encountered inside the run */
    ValidateResult result; /* VR_PASS / VR_INCONCLUSIVE / VR_FAIL */
    uint64_t span_bytes; /* how big the validated span is */
} DynamicScanResult;


/* 
    DynamicView is a cheap extracted summary of DT_ metadata* from a candidate’s .dynamic region. 
    It allows for powerful cross-valiation with components such as relocations, symbols, and strings.
    
    These structures do not persist in memory. 
*/
typedef struct {
    /* Relocations (main) */
    bool     has_rela;
    uint64_t rela_va;
    uint64_t rela_sz;
    uint64_t rela_ent;

    bool     has_rel;
    uint64_t rel_va;
    uint64_t rel_sz;
    uint64_t rel_ent;

    /* PLT relocations */
    bool     has_jmprel;
    uint64_t jmprel_va;
    uint64_t jmprel_sz;
    bool     jmprel_is_rela;

    /* Dynamic symbols / strings */
    bool     has_symtab;
    uint64_t symtab_va;
    uint64_t syment;

    bool     has_strtab;
    uint64_t strtab_va;
    uint64_t strsz;

    /* Hash tables  */
    bool     has_sysv_hash;
    uint64_t sysv_hash_va;
    uint32_t dynsym_count_sysv;

    bool     has_gnu_hash;
    uint64_t gnu_hash_va;
    uint32_t gnu_symoffset;

    /* Policy bits */
    bool     textrel_present;
} DynamicView;


/* ------------------------------------------------------------
 * structs for representing ELF structures used in cross validation
 * ------------------------------------------------------------ */

 // (currently not used; cross-validation disabled)
 // These structures store information that can be parsed out
 // of various tables in the executable

// PT_LOAD segment representation
typedef struct {
    uint32_t seg_type;
    uint64_t seg_offset;    // File offset (p_offset)
    uint64_t seg_file_size; // File size (p_filesz)
    uint64_t seg_vaddr;     // Virtual address (p_vaddr)
    uint64_t seg_mem_size;  // Memory size (p_memsz)
} SegmentInfo;


// Relocation entry 
typedef struct {
    uint32_t r_offset;  // File offset to relocate
    uint32_t r_info;    // Relocation type + symbol index
} Elf32_Rel;

typedef struct {
    uint32_t r_offset;  // File offset to relocate
    uint32_t r_info;    // Relocation type + symbol index
    int32_t  r_addend;  // Addend value
} Elf32_Rela;

typedef struct {
    uint64_t r_offset;  // File offset to relocate
    uint64_t r_info;    // Relocation type + symbol index
} Elf64_Rel;

typedef struct {
    uint64_t r_offset;  // File offset to relocate
    uint64_t r_info;    // Relocation type + symbol index
    int64_t  r_addend;  // Addend value
} Elf64_Rela;


// Symbol entry structures
typedef struct {
    uint32_t st_name;   // Symbol name offset in string table
    uint32_t st_value;  // Symbol value (address)
    uint32_t st_size;   // Symbol size
    uint8_t  st_info;   // Symbol type + binding
    uint8_t  st_other;  // Visibility
    uint16_t st_shndx;  // Section header index
} Elf32_Sym;

typedef struct {
    uint32_t st_name;   // Symbol name offset in string table
    uint8_t  st_info;   // Symbol type + binding
    uint8_t  st_other;  // Visibility
    uint16_t st_shndx;  // Section header index
    uint64_t st_value;  // Symbol value (address)
    uint64_t st_size;   // Symbol size
} Elf64_Sym;


/* ------------------------------------------------------------
 * Block scoring and reassembly configuration
 * ------------------------------------------------------------ */

// Max number of components the block validator can tie to blocks
#define ELF_MAX_BLOCK_COMPONENTS 20u
// Max number of section header entries a single SHT can have
#define ELF_MAX_SHT_ENTRIES 256u
// Max number of bytes a dynamic section is allowed to have
#define ELF_MAX_DYNAMIC_BYTES (256u * 1024u) 

/*
    Coverage stats used by block scoring to quanitfy how well a segmentation map
    matches the expected block profile. 

    These structs are allocated as local temporaries inside the coverage computation routines 
    (stack/ephemeral) and are not persisted across blocks the way BlockState and FileState are.
*/
typedef struct {
    /* Mass (complement-based unknown) */
    uint64_t expected_known_bytes;     /* union of known(expected) */
    uint64_t expected_unknown_bytes;   /* blocksize - expected_known_bytes */

    /* Agreement / violation accounting */
    uint64_t matched_known_bytes;      /* bytes where expected+observed agree on SAME known section id */
    uint64_t unk_agree_bytes;          /* bytes where expected unknown AND observed unknown */

    /* Derived rates */
    double known_cov;                 /* matched_known / expected_known */
    double unknown_cov;               /* unk_agree / expected_unknown */
    double coverage;                  /* weighted mix: (matched_known + w*unk_agree)/(expected_known + w*expected_unknown) */

    /* Gatekeeping */
    bool expected_has_known;          /* expected_known_bytes > 0 */
} CoverageStats;



/* ============================================================================
 * ElfTunables
 *
 * Purpose:
 *   Central bundle of tunable knobs for the ELF fragmented reassembly engine.
 *   Controls block scoring (coverage matching, cross-validation, locality),
 *   search policy (window sizing, iteration budgets), placement thresholds,
 *   gallop behavior, seed/preview scoring, and the final .text fill pass.
 *
 *   All values are kept as data so behavior can be calibrated, logged, and
 *   swept for a given corpus or storage medium without touching code. The
 *   defaults (set in default_elf_tunables()) are tuned for typical ELF
 *   binaries on rotational and SSD media with moderate fragmentation.
 *
 *   Tuning guidance:
 *     - Highly fragmented images: lower tau_place_* thresholds, raise
 *       weak_streak_max, raise textfrag_max_* limits.
 *     - Low-fragmentation / forensic images with many false positives: raise
 *       tau_place_* and known_hard_min_cov to be more selective.
 *     - Large corpora with many small ELF files: lower max_iters and
 *       search_max_steps to control runtime.
 *     - Flash / NAND media (block-aligned, low locality): set adj_* bonuses
 *       to zero and raise ibl_* lambdas to de-emphasize locality.
 *
 * Memory:
 *   Negligible. One instance per thread (or per run). Does not scale with
 *   disk size or number of candidates.
 * ========================================================================== */

typedef struct {

    /* ===================================================================
    * TABLE DETECTION POLICY (SHT / PHT block scanner)
    * =================================================================== */

    uint32_t min_consecutive_valid_sht_entries;
    /* Minimum run of valid SHT entries required before a region is
    * accepted as a Section Header Table. Default: 8. */

    uint32_t min_consecutive_valid_pht_entries;
    /* Minimum run of valid PHT entries required before a region is
    * accepted as a Program Header Table. Default: 8. */

    double sht_max_null_fraction;
    /* Maximum fraction of a qualifying SHT run that may consist of
    * NULL-type entries. Runs exceeding this are rejected. Default: 0.5. */

    double sht_max_degenerate_fraction;
    /* Maximum fraction of a qualifying SHT run that may consist of
    * degenerate (all-zero key fields) entries. Default: 0.333. */

    double pht_max_null_fraction;
    /* Maximum fraction of a qualifying PHT run that may consist of
    * PT_NULL entries (excluding a legitimate leading PT_NULL).
    * Default: 0.5. */

    double pht_max_degenerate_fraction;
    /* Maximum fraction of a qualifying PHT run that may consist of
    * degenerate entries. Default: 0.333. */

    uint32_t pht_load_required_min_entries;
    /* Minimum run length at which at least one PT_LOAD segment is
    * required. Shorter runs are accepted without PT_LOAD to avoid
    * false negatives on small or stripped binaries. Default: 6. */

    uint32_t sht_empty_section_min_run;
    /* Minimum number of valid entries already seen before a zero-size
    * non-NULL section entry is tolerated. Default: 8. */

    uint32_t sht_max_empty_nonnull;
    /* Maximum number of zero-size non-NULL entries tolerated per run.
    * Default: 1. */

    /* ===================================================================
    * .SHSTRTAB STRUCTURAL VALIDATION
    * =================================================================== */

    uint32_t shstr_min_tokens;
    /* Minimum number of NUL-separated name tokens required in a candidate
    * .shstrtab slice. Default: 3. */

    uint32_t shstr_min_dot_pct;
    /* Minimum percentage (0-100) of tokens that must begin with '.'.
    * Default: 30. */

    uint32_t shstr_max_token_len;
    /* Maximum byte length of a single section name token. Used in both
    * slice validation and sh_name cross-reference validation. Default: 96. */

    uint32_t shstrtab_sht_min_resolve_pct;
    /* Minimum percentage (0-100) of SHT sh_name offsets that must resolve
    * to valid names inside the candidate .shstrtab. Default: 67. */

    /* ===================================================================
     * BASE MATCHER  (logit space)
     *
     * The primary evidence signal is coverage: how well the ONNX-classified
     * section layout of the observed block matches the ground-truth layout
     * derived from the SHT/PHT skeleton.
     *
     * Coverage is converted to a logit via:
     *   base_logit = logit(coverage)
     * then penalized for wrong-section and extra-known bytes.
     * =================================================================== */

    double prob_eps;
    /* Clamps all probabilities to [prob_eps, 1 - prob_eps] before taking
     * logits, preventing ±inf. Rarely needs changing; only lower it if you
     * have extremely high-confidence per-block classifiers. Default: 1e-6. */

    double unknown_cov_weight;
    /* Weight [0..1] given to unknown-region agreement in the blended coverage
     * formula:
     *   coverage = (matched_known + w * unk_agree) /
     *              (expected_known + w * expected_unknown)
     * At 0, only known-section agreement matters. At 1, unknown agreement
     * counts equally. Raise if blocks frequently contain large unclassified
     * regions (e.g., padding, compressed content). Default: 0.10. */


    /* ===================================================================
     * STRUCTURED CROSS-VALIDATION EVIDENCE  (logit weights)
     *
     * These weights gate optional bonuses/penalties derived from deeper
     * structural checks (e.g., scanning a block for valid dynamic entries,
     * relocation records, or symbol tables and comparing against the skeleton).
     * Currently disabled pending calibration; kept here for future use.
     * =================================================================== */

    double dyn_scan_w;          /* bonus for a valid .dynamic scan hit */
    double dyn_scan_null_w;     /* bonus for a clean .dynamic null terminator */
    double dyn_validate_w;      /* bonus for full .dynamic structural validation */

    double reloc_scan_w;        /* bonus for valid relocation entry scan */
    double reloc_validate_dyn_w;/* bonus for relocation entries consistent with .dynamic */
    double reloc_validate_sht_w;/* bonus for relocation entries consistent with SHT */

    double sym_scan_w;          /* bonus for valid symbol table scan */
    double sym_validate_dyn_w;  /* bonus for symbols consistent with .dynamic */

    double strtab_validate_w;   /* bonus for a well-formed string table */

    double dyn_fail_w;          /* penalty (negative) for a failed .dynamic check */
    double reloc_fail_w;        /* penalty (negative) for a failed relocation check */
    double sym_fail_w;          /* penalty (negative) for a failed symbol check */
    double strtab_fail_w;       /* penalty (negative) for a failed string table check */


    /* ===================================================================
     * CROSS VALIDATION SETTINGS
     *
     * CV can optionally be enabled (recommended) to perform semantic 
     * validation across various elf structures where applicable. 
     * 
     * If this is enabled, the code will perform extra structural and 
     * cross-validation with other sections. The main sections that have
     * cross-validation logic include dynamic, relocations, symbols, and 
     * strings. These are the primary sections structured enough and 
     * containing enough useful context for cross-validation. Unstructured 
     * or rarely occurring sections are not included, since context is 
     * either non-existent or minimally useful in practice. 
     * =================================================================== */

    double damp25_factor;
    /* Multiplier [0..1] applied to CV and locality logits when weighted
     * coverage < 0.25. At 0.25 (the default), supplementary evidence counts
     * for only a quarter of its face value for very low-coverage blocks.
     * Set to 0.0 to completely suppress supplementary evidence in this range.
     * Default: 0.25. */

    double damp50_factor;
    /* Multiplier [0..1] applied to CV and locality logits when weighted
     * coverage is in [0.25, 0.50). A gentler damping than damp25_factor,
     * allowing moderate supplementary evidence to contribute for mediocre
     * coverage blocks. Default: 0.60. */

    bool expand_by_tolerance;
    /* If true, the intra-block locality (IBL) scorer normalizes offset and
     * size deltas by the per-section ELF tolerance before computing the
     * exponential bonus (see ibl_scale_by_tol). Set to false to use raw
     * byte deltas, which makes the IBL bonus section-size-invariant but
     * less adaptive to section-specific layout variance. Default: true. */

    bool enable_cv;
    /* If true, structured cross-validation bonuses are applied on top of
     * the coverage score for DYNAMIC, RELOCATION, SYMBOL, and STRING
     * sections. Currently disabled pending calibration. Default: false. */


    /* ===================================================================
     * SEARCH / CHOOSER POLICY
     *
     * Shared limits governing how far and how long the placement engine
     * is willing to search for a block to fill each slot.
     * =================================================================== */

    uint64_t search_max_steps;
    /* Maximum steps (block evaluations) per gallop pass. The gallop stops
     * early if it hits a hard boundary (OOB, covered block, section
     * mismatch), so in practice this is an upper safety bound rather than a
     * typical limit. Raise for very large or highly fragmented images where
     * long contiguous runs are expected. Default: 2000. */

    uint64_t max_evals;
    /* Maximum candidate apparent blocks evaluated per call to the block
     * chooser (elf_reassembly_get_block_choice). Controls the per-slot
     * search budget. Raise if good blocks are being missed because the
     * window is exhausted before they are reached; lower to reduce runtime
     * on large images with many candidates. Default: 2000. */

    uint64_t window_cap;
    /* Hard cap on the local search window: the chooser will not evaluate
     * apparent blocks more than window_cap positions away from the predicted
     * location (ap_pred) in either direction, regardless of window expansion.
     * Prevents runaway search on images with pathological block distributions.
     * Raise for very large images or when section placement is highly
     * unpredictable. Default: 2048. */

    uint32_t window_expand_delta;
    /* When the chooser exhausts the current AP window without finding an
     * acceptable seed, it expands the window by this many apparent blocks on
     * each side before trying again (up to window_cap). Set to 0 to disable
     * expansion (the chooser will not search beyond its initial window).
     * Default: 128. */


    /* ===================================================================
     * PLACEMENT AND BOUNDARY THRESHOLDS
     *
     * These control when the engine commits a block to a slot (tau_place_*)
     * and how aggressively boundary context is respected in preview scoring.
     * =================================================================== */

    double boundary_floor;
    /* When a preview run hits a ground-truth section boundary and the run
     * length ratio (run_len / L_target) would otherwise be very low, it is
     * clamped up to boundary_floor before entering the score formula. This
     * prevents boundary-adjacent blocks from being penalized purely for short
     * runs when the boundary itself explains the run length. Raise to give
     * boundary hits more benefit of the doubt; lower to require longer runs
     * even at boundaries. Default: 0.35. */

    double tau_place_main;
    /* Minimum posterior probability required for the block chooser to accept
     * a seed as a placement candidate. This is the primary acceptance gate
     * for the seed-and-preview search. Lower values accept weaker matches
     * (more placements, higher recall, higher false-positive risk); higher
     * values demand stronger evidence (fewer placements, higher precision).
     * Typical range: 0.25–0.50. Default: 0.30. */

    double tau_place_gallop_init;
    /* Acceptance threshold used during the initial gallop pass that runs
     * immediately after skeleton initialization. This pass fills in obvious
     * neighbors of the already-placed header block, so a higher threshold
     * than tau_place_main is appropriate to avoid committing to weak matches
     * before the search has calibrated. Default: 0.60. */

    double tau_place_gallop_loop;
    /* Acceptance threshold used for gallop passes triggered after each
     * block-choice placement during the main reassembly loop. Lower than
     * tau_place_gallop_init because by this point the surrounding context is
     * better established. Default: 0.60. */


    /* ===================================================================
     * GALLOP POLICY
     *
     * The gallop extends a just-placed block greedily in one or both
     * directions by committing sequentially-scored blocks without a full
     * seed-and-preview search. It uses hysteresis thresholds derived from
     * tau_place to avoid oscillation.
     * =================================================================== */

    double gallop_tau_hyst;
    /* Hysteresis margin subtracted from the entry tau to produce the
     * continuation tau:
     *   tau_continue = tau_enter - gallop_tau_hyst
     * Once the gallop has committed at least one block, it continues
     * accepting blocks at this lower threshold, preventing it from stopping
     * the moment a slightly weaker block is encountered. Default: 0.05. */

    double gallop_tau_stop_margin;
    /* Further margin subtracted from tau_continue to produce the hard-stop
     * threshold:
     *   tau_stop = tau_continue - gallop_tau_stop_margin
     * A block scoring below tau_stop causes an immediate gallop termination.
     * Blocks between tau_stop and tau_continue are staged as "weak" and
     * committed only if a strong block later closes the streak.
     * Default: 0.02. */

    uint32_t weak_streak_max;
    /* Maximum number of consecutive weak-scoring (non-unknown) blocks the
     * gallop will stage before discarding them and stopping. A staged block
     * is committed only when a subsequent strong block validates the streak.
     * Raise on highly fragmented images where isolated weak blocks often
     * appear inside otherwise strong runs. Default: 3. */


    /* ===================================================================
     * SEED + PREVIEW POLICY
     *
     * Before committing to a placement, the chooser runs a "preview" pass
     * that scores a short forward (and optionally backward) run of blocks
     * starting from each seed candidate. The preview result determines
     * whether the seed is retained in the top-M set.
     * =================================================================== */

    double preview_p_stop;
    /* Per-step probability threshold below which a preview run is terminated
     * early. If any block in the run scores below this value, the run ends
     * and the seed's score reflects only the steps completed. Lower values
     * allow the preview to push through weaker blocks; higher values cut
     * runs short aggressively. Default: 0.55. */

    uint32_t preview_min_known_scored;
    /* Minimum number of steps in a preview run that must involve blocks with
     * known (non-unknown) expected content before the run's score is
     * considered valid. Prevents the chooser from selecting a seed based
     * solely on runs through all-unknown padding slots. Default: 1. */

    uint32_t preview_max_len;
    /* Maximum number of steps in a preview run, regardless of how many
     * valid steps remain. Caps the per-seed evaluation cost. Raise if the
     * top seeds are consistently being scored on too-short runs; lower to
     * reduce per-step overhead on large blockvectors. Default: 24. */

    uint32_t preview_boundary_D;
    /* Look-ahead distance (in BV slots) when searching for a ground-truth
     * section boundary adjacent to the slot being evaluated. Used to set
     * the preview's L_target (expected run length to the boundary).
     * Raise if boundaries are often missed because they fall outside the
     * default window. Default: 12. */

    bool preview_eval_bidir;
    /* If true, each seed candidate is evaluated in both directions (+1 and
     * -1 in BV order) and the better score is retained. Doubles per-seed
     * preview cost but significantly improves seed selection when the
     * correct fill direction is ambiguous. Disable on resource-constrained
     * runs. Default: true. */

    uint32_t seed_topM;
    /* Number of top-scoring seeds to retain per chooser call. The best seed
     * (by preview score) is selected as the placement. Increasing M allows
     * the chooser to consider more candidates per slot but increases memory
     * and evaluation cost proportionally. Default: 4. */

    double preview_len_conf_floor;
    /* Minimum length confidence factor applied to the seed score formula.
     * A run of zero length receives this as its length factor; a full-length
     * run (preview_max_len steps) receives 1.0. The score is:
     *   score = avg_p * tail_p * (preview_len_conf_floor +
     *           (1.0 - preview_len_conf_floor) * run_len / preview_max_len)
     * At 0.5, a single-step run receives half the weight of a full run.
     * Set to 1.0 to disable length confidence scaling entirely (reverts to
     * plain avg_p * tail_p). Default: 0.5. */

    double tau_boundary;
    /* Minimum posterior probability required for the step-0 block of a
     * preview run when the seed falls on a multi-section boundary slot.
     * Stricter than preview_p_stop because a boundary block anchors many
     * subsequent gallop placements — a weak anchor propagates errors far.
     * Default: 0.85. */

    uint32_t tail_k;
    /* Number of lowest per-step probabilities averaged to produce tail_p,
     * the robustness statistic used in seed scoring:
     *   tail_p = mean of the tail_k lowest p values seen in the preview run
     * A higher tail_k is less sensitive to a single outlier weak step.
     * tail_k = 1 uses only the single worst step. Default: 2. */

    uint32_t boundary_dual_min_bytes;
    /* Minimum observed overlap in bytes for a section to count as supported
     * in the dual-section boundary gate. A step-0 boundary seed must show
     * classifier evidence for at least two expected sections; this sets the
     * minimum byte overlap required per section. Default: 64. */

    double boundary_dual_min_frac;
    /* Minimum fraction of expected bytes that must overlap with observed
     * bytes for a section to count as supported in the dual-section boundary
     * gate. Both boundary_dual_min_bytes and boundary_dual_min_frac must be
     * satisfied. Default: 0.10. */

    /* ===================================================================
     * STOPPING POLICY
     *
     * How long to try reassembling before abandoning a candidate
     * =================================================================== */

    uint64_t max_iters;
    /* Maximum outer reassembly loop iterations before stopping regardless
     * of placement progress. A hard safety bound for pathological candidates.
     * Default: 500000. */

    uint64_t max_no_progress;
    /* Maximum consecutive iterations with no block placed before the
     * reassembly loop stops. Prevents spinning when no further progress
     * is possible. Default: 20000. */


    /* ===================================================================
     * TEXT FRAGMENT COLLECTION POLICY
     *
     * After the main placement loop, elf_reassembly_fill_text_holes_final()
     * tries to fill remaining pure-.text holes by collecting globally
     * available .text-like block runs ("fragments") and matching them to
     * same-length holes. These knobs control how permissive fragment
     * collection is when the run passes through weaker blocks.
     *
     * Fragment runs must start on a FULL .text block. They extend through
     * PARTIAL, UNKNOWN, and OTHER blocks subject to the limits below.
     * A pending weak tail is only committed when a subsequent FULL block
     * closes it.
     *
     * Raise limits for corpora with many partial or ambiguous .text blocks
     * (e.g., hand-crafted or packed ELFs). Lower limits to suppress
     * false .text placements on clean corpora.
     * =================================================================== */

    uint32_t textfrag_max_consec_partial;
    /* Maximum number of consecutive PARTIAL .text blocks allowed within a
     * fragment run before the run is terminated. Default: 3. */

    uint32_t textfrag_max_total_partial;
    /* Maximum total PARTIAL blocks permitted across the entire fragment run.
     * Caps the overall proportion of ambiguous blocks even if they are
     * spread non-consecutively. Default: 10. */

    uint32_t textfrag_max_consec_unknown;
    /* Maximum consecutive UNKNOWN (unclassified) blocks allowed within a
     * fragment run. UNKNOWN blocks represent disk blocks for which no section
     * classifier evidence exists; allowing 1 bridges single-block gaps (e.g.,
     * filesystem metadata) without admitting long ambiguous stretches.
     * Default: 1. */

    uint32_t textfrag_max_total_unknown;
    /* Maximum total UNKNOWN blocks across the fragment run. Default: 5. */

    uint32_t textfrag_max_consec_other;
    /* Maximum consecutive OTHER blocks (blocks with known section evidence
     * for a non-.text section) allowed within a .text fragment run. These
     * are the most suspicious and should be kept tightly bounded.
     * Default: 1. */

    uint32_t textfrag_max_total_other;
    /* Maximum total OTHER blocks across the fragment run. Default: 5. */

} ElfTunables;



static inline ElfTunables default_tunables(void)
{
    ElfTunables sp;

    /* --- Table detection --- */
    sp.min_consecutive_valid_sht_entries = 8;
    sp.min_consecutive_valid_pht_entries = 8;
    sp.sht_max_null_fraction             = 0.5;
    sp.sht_max_degenerate_fraction       = 0.333;
    sp.pht_max_null_fraction             = 0.5;
    sp.pht_max_degenerate_fraction       = 0.333;
    sp.pht_load_required_min_entries     = 6;
    sp.sht_empty_section_min_run         = 8;
    sp.sht_max_empty_nonnull             = 1;

    /* --- .shstrtab structural validation --- */
    sp.shstr_min_tokens             = 3;
    sp.shstr_min_dot_pct            = 30;
    sp.shstr_max_token_len          = 96;
    sp.shstrtab_sht_min_resolve_pct = 67;

    /* --- Base matcher --- */
    sp.prob_eps                = 1e-6;

    sp.unknown_cov_weight      = 0.10;

    /* --- Structured evidence (logits) --- */
    sp.dyn_scan_w              = 0.8;
    sp.dyn_scan_null_w         = 0.4;
    sp.dyn_validate_w          = 1.2;

    sp.reloc_scan_w            = 0.7;
    sp.reloc_validate_dyn_w    = 1.0;
    sp.reloc_validate_sht_w    = 0.9;

    sp.sym_scan_w              = 0.6;
    sp.sym_validate_dyn_w      = 0.9;

    sp.strtab_validate_w       = 0.8;

    sp.dyn_fail_w              = -0.8;
    sp.reloc_fail_w            = -1.0;
    sp.sym_fail_w              = -0.9;
    sp.strtab_fail_w           = -0.8;

    /* --- Evidence damping --- */
    sp.damp25_factor           = 0.25;
    sp.damp50_factor           = 0.60;
    sp.expand_by_tolerance     = true;
    sp.enable_cv               = true;

    /* --- Search / chooser policy --- */
    sp.search_max_steps        = 500;
    sp.max_evals               = 500;
    sp.window_cap              = 2048;
    sp.window_expand_delta     = 128;

    /* --- Placement / boundary thresholds --- */
    sp.boundary_floor          = 0.35;

    sp.tau_place_main          = 0.30;
    sp.tau_place_gallop_init   = 0.60;
    sp.tau_place_gallop_loop   = 0.60;

    /* --- Gallop / driver policy --- */
    sp.gallop_tau_hyst         = 0.05;
    sp.gallop_tau_stop_margin  = 0.02;
    sp.weak_streak_max         = 3;

    /* --- Seed + preview defaults (conservative) --- */
    sp.preview_p_stop               = 0.55;
    sp.preview_min_known_scored     = 1;
    sp.preview_max_len              = 24;
    sp.preview_boundary_D           = 12;
    sp.preview_eval_bidir           = true;

    sp.seed_topM                    = 4;
    sp.preview_len_conf_floor = 0.5;
    sp.tau_boundary            = 0.85;
    sp.tail_k                  = 2;
    sp.boundary_dual_min_bytes = 64;
    sp.boundary_dual_min_frac  = 0.10;
    sp.max_iters               = 500000;
    sp.max_no_progress         = 20000;

    /* --- Text-fragment collection policy --- */
    sp.textfrag_max_consec_partial  = 3;
    sp.textfrag_max_total_partial   = 10;

    sp.textfrag_max_consec_unknown  = 1;
    sp.textfrag_max_total_unknown   = 5;

    sp.textfrag_max_consec_other    = 1;
    sp.textfrag_max_total_other     = 5;

    return sp;
}


/***************************************************************/
/*         ELF ENUM DEFINITIONS (FOR READABILITY)              */
/***************************************************************/

enum Endianness {LITTLE = 0, BIG = 1};

// Possible block and file component types
typedef enum {
    COMPONENT_ELF_HEADER = 0,
    COMPONENT_PHT,
    COMPONENT_SHT,
    COMPONENT_SECTION,
    COMPONENT_UNKNOWN
} ElfComponentType;

// Supported section categories
typedef enum {
    SECTION_UNKNOWN = 0,
    SECTION_GOT,
    SECTION_SYMBOL,
    SECTION_PLT,
    SECTION_STRING,
    SECTION_DYNAMIC,
    SECTION_EH_FRAME,
    SECTION_EH_FRAME_HEADER,
    SECTION_TEXT,
    SECTION_RELOCATION,
    SECTION_SHSTRTAB
} SectionDataType;


// Used in computational geometry / interval arithmetic that is used for block scoring. 
typedef struct {
    uint32_t s;      /* inclusive */
    uint32_t e;      /* exclusive */
    SectionDataType sec;
} SecSpan;


/* Result codes for elf_reassembly_get_block_choice() / windowed choice scanning. */
typedef enum {
    ELF_CHOICE_FOUND = 0,   /* A usable apparent block choice was found (out_ap_choice valid). */
    ELF_WINDOW_EMPTY,       /* No usable choice found within this scan window; more choices may remain. */
    ELF_CHOICE_EXHAUSTED   /* No usable choice exists for this slot (full cycle / all remaining choices eliminated). */
} ElfChoiceResult;


#ifdef __BYTE_ORDER__
    #if __BYTE_ORDER__ == __ORDER_BIG_ENDIAN__
        #define TARGET_ENDIANNESS BIG
    #else
        #define TARGET_ENDIANNESS LITTLE
    #endif
#endif


/***************************************************************/
/*             ELF FILE SPECIFICATION STRUCTURES               */
/***************************************************************/


/*
    These Structs represent the ELF header for 32-bit and 64-bit
    respectively, starting from offset 0x10, where fields are multi-byte
    and endianness becomes relevant.

    They can be used to easily parse fields of idenitified ELF headers.
*/

typedef struct {
    uint16_t exec_type;
    uint16_t isa;
    uint32_t elf_ver;
    uint32_t entry_point;
    uint32_t pht_off;
    uint32_t sht_off;
    uint32_t flags;
    uint16_t elf_header_size;
    uint16_t pht_entry_size;
    uint16_t num_pht_entries;
    uint16_t sht_entry_size;
    uint16_t num_sht_entries;
    uint16_t idx_section_names;

} Elf_Header_32;



typedef struct {
    uint16_t exec_type;
    uint16_t isa;
    uint32_t elf_ver;
    uint64_t entry_point;
    uint64_t pht_off;
    uint64_t sht_off;
    uint32_t flags;
    uint16_t elf_header_size;
    uint16_t pht_entry_size;
    uint16_t num_pht_entries;
    uint16_t sht_entry_size;
    uint16_t num_sht_entries;
    uint16_t idx_section_names;

} Elf_Header_64;


/*
    These Structs represent the PHT entries for 32-bit and 64-bit
    respectively. They can be used to easily parse fields of idenitified
    PHT entries.
*/
typedef struct {
    uint32_t seg_type;
    uint32_t seg_offset;
    uint32_t seg_vaddr;
    uint32_t seg_physaddr;
    uint32_t seg_file_size;
    uint32_t seg_mem_size;
    uint32_t flags_32;
    uint32_t alignment;

} Program_Header_Entry_32;


typedef struct {
    uint32_t seg_type;
    uint32_t flags_64;
    uint64_t seg_offset;
    uint64_t seg_vaddr;
    uint64_t seg_physaddr;
    uint64_t seg_file_size;
    uint64_t seg_mem_size;
    uint64_t alignment;

} Program_Header_Entry_64;


/*
    These Structs represent the SHT entries for 32-bit and 64-bit
    respectively. They can be used to easily parse fields of idenitified
    SHT entries.
*/
typedef struct {
    uint32_t sect_name_off;
    uint32_t section_type;
    uint32_t flags;
    uint32_t sect_mem_addr;
    uint32_t sect_file_off;
    uint32_t sect_size;
    uint32_t sect_idx;
    uint32_t sect_info;
    uint32_t sect_align;
    uint32_t entry_size;

} Section_Header_Entry_32;


typedef struct {
    uint32_t sect_name_off;
    uint32_t section_type;
    uint64_t flags;
    uint64_t sect_mem_addr;
    uint64_t sect_file_off;
    uint64_t sect_size;
    uint32_t sect_idx;
    uint32_t sect_info;
    uint64_t sect_align;
    uint64_t entry_size;

} Section_Header_Entry_64;



/***************************************************************/
/*                ELF SCALPEL STATE STRUCTURES                 */
/***************************************************************/

/**
 * BlockComponent — A single contiguous region of known content within one
 * disk block.
 *
 * During block validation (elf_block_validate), the ONNX classifier produces
 * a byte-level classification against supported ELF section categoies.
 * The post-processing cleans these maps and identifies contiguous section
 * data based on geometric properties. 
 * 
 * Each contigous region becomes one BlockComponent entry. The full set of
 * entries for a block is stored in BlockState and persisted via
 * block_put_state so that any later placement pass can retrieve it without
 * re-running the classifier.
 *
 * Coordinates are block-local: blockOffset is relative to the start of the
 * block, not the start of the image file. A block may contain up to
 * ELF_MAX_BLOCK_COMPONENTS (20) entries; additional regions beyond that cap
 * are silently dropped. Blocks ordinarily do not have more than 20 bock 
 * components since the post-processing cleans the maps, smooths regions, and
 * eliminates false positives, so the cap is included primarily as a safe-guard. 
 *
 * type and section together identify what the region contains:
 *   - COMPONENT_ELF_HEADER: the ELF identification header.
 *   - COMPONENT_PHT:        a Program Header Table.
 *   - COMPONENT_SHT:        a Section Header Table.
 *   - COMPONENT_SECTION:    a named section; section specifies which one.
 *   - COMPONENT_UNKNOWN:    unclassified content (complement fill).
 * For all types other than COMPONENT_SECTION, section is meaningless and
 * should be ignored.
 */
typedef struct {

    ElfComponentType type;
    /* Coarse category of this region. One of COMPONENT_ELF_HEADER,
     * COMPONENT_PHT, COMPONENT_SHT, COMPONENT_SECTION, or
     * COMPONENT_UNKNOWN. Determines how the entry is interpreted by
     * coverage matching and placement logic. */

    SectionDataType section;
    /* Fine-grained section identity. Only meaningful when type ==
     * COMPONENT_SECTION. One of SECTION_TEXT, SECTION_DYNAMIC,
     * SECTION_RELOCATION, SECTION_SYMBOL, SECTION_STRING, SECTION_GOT,
     * SECTION_PLT, SECTION_SHSTRTAB, or SECTION_UNKNOWN. Ignored for
     * all other component types. */

    uint64_t blockOffset;
    /* Byte offset of this region from the start of the block. Combined
     * with size, defines the half-open interval [blockOffset,
     * blockOffset + size) within the block's bytes. */

    uint64_t size;
    /* Length of this region in bytes. */

} BlockComponent;


/**
 * FileComponent — A single contiguous region of the reconstructed ELF file
 * as derived from the ground-truth skeleton.
 *
 * The skeleton builder (build_candidate_state_64/32) parses the Section
 * Header Table and .shstrtab which are located and reassembled using ELF 
 * header offset information.
 * 
 * FileComponents are used to describe a logically contiguous region of the 
 * target file: the ELF header, the PHT, the SHT, section categories, and any 
 * uncovered gaps, which include padding regions and arbitrary data not supported 
 * by current detection logic (filled as COMPONENT_UNKNOWN). These entries are 
 * stored in FileState and serve as the ground truth that all block placement 
 * decisions are measured against.
 *
 * Coordinates are file-local: fileOffset is an absolute byte offset within
 * the reconstructed ELF file, not within any single disk block. The coverage
 * matcher projects FileComponent extents into individual block windows by
 * intersecting [fileOffset, fileOffset + size) with each block's file range.
 *
 * type and section follow the same semantics as in BlockComponent.
 */
typedef struct {

    ElfComponentType type;
    /* Coarse category of this file region. Same set of values as
     * BlockComponent.type. COMPONENT_UNKNOWN is used for gap regions
     * between known sections. */

    SectionDataType section;
    /* Fine-grained section identity. Only meaningful when type ==
     * COMPONENT_SECTION. Same set of values as BlockComponent.section. */

    uint64_t fileOffset;
    /* Absolute byte offset of this region from the start of the
     * reconstructed ELF file. Combined with size, defines the half-open
     * interval [fileOffset, fileOffset + size) in file space. */

    uint64_t size;
    /* Length of this region in bytes. */

} FileComponent;


/**
 * BlockState — The complete set of classified regions for one disk block,
 * persisted across reassembly calls.
 *
 * After elf_block_validate runs the ONNX classifier over a block, the
 * resulting BlockComponent array is packaged into a BlockState and written
 * to the block hashtable via block_put_state. Any subsequent reassembly
 * pass can retrieve it with block_get_state, inspect the classified regions,
 * and free the local handle with elf_free_block_state without disturbing the
 * stored copy.
 *
 * BlockState is treated as immutable after it has been committed to the
 * hashtable. Placement and scoring code reads components[] but must not
 * modify its entries.
 *
 * Ownership: block_put_state takes a deep copy; the caller is responsible
 * for freeing the handle returned by block_get_state via elf_free_block_state.
 * The components array is heap-allocated and freed by elf_free_block_state.
 * num_components may be zero if the classifier found no recognizable content
 * in the block.
 */
typedef struct {

    BlockComponent *components;
    /* Heap-allocated array of classified regions within this block, in
     * ascending blockOffset order. May be NULL if num_components is zero.
     * Each entry describes one contiguous region identified by the ONNX
     * classifier during elf_block_validate. Freed by elf_free_block_state. */

    size_t num_components;
    /* Number of valid entries in components[]. Zero indicates the
     * classifier found no recognizable content; the block is treated as
     * entirely unknown by the coverage scorer. Capped at
     * ELF_MAX_BLOCK_COMPONENTS (20) at construction time. */

} BlockState;


/*
    ELF file state: Describes all of the components in a candidate
    with positional / offset information.
    Array 'slots_with_choices' included to aid in backtracking logic.
*/
/* Hard cap for persisted top-M entries (compile-time). */
#ifndef ELF_SEED_TOPM_MAX
#define ELF_SEED_TOPM_MAX 16
#endif

/**
 * ElfSeedSearchState — Per-slot seed search state for the ELF fragmented
 * reassembly engine.
 *
 * During block placement, the chooser must find the best apparent-block
 * number (AP) to assign to each unfilled slot in the candidate BlockVector.
 * It does this by enumerating "seed" candidates within a windowed region of
 * AP space, running a short preview pass over each one, and retaining the
 * top-M scorers in a sorted table. The winning seed (top[0]) is returned as
 * the placement choice for that slot.
 *
 * Because the search is expensive and may be interrupted mid-scan (e.g. to
 * persist state and yield), this struct captures the full enumerator state
 * so that the scan can be resumed exactly where it left off on the next call.
 * It is embedded in FileState and persisted via carve_put_state /
 * carve_get_state.
 *
 * Lifecycle:
 *   - Initialized (memset + active=1) at the start of each new slot search.
 *   - Updated in-place as seeds are evaluated and the window expands.
 *   - Cleared (active=0) once a placement decision has been made or the
 *     search is exhausted for a given slot.
 *   - The identity fields (bv_target, focus) allow the resume path to detect
 *     stale state from a prior slot and trigger a fresh init if needed.
 *
 * Window expansion:
 *   The search starts with a narrow AP window [ap_lo, ap_hi] centered on
 *   ap_pred and expands outward each time the ring enumerator exhausts all
 *   candidates in the current window, up to the hard corridor [ap_cap_lo,
 *   ap_cap_hi]. Each expansion increments stage.
 *
 * Scoring:
 *   Each seed is scored as: avg_p * tail_p * length_confidence_factor.
 *   avg_p is the mean per-step classifier probability over the preview run;
 *   tail_p is the mean of the two lowest per-step probabilities (softened
 *   worst-case); the length factor scales the score down for short runs.
 *   Seeds are retained in the top[] table in descending score order.
 */
typedef struct {

    /* ------------------------------------------------------------------ */
    /* Control                                                              */
    /* ------------------------------------------------------------------ */

    uint8_t active;
    /* 0 = this state is empty/stale and should be ignored or reinitialised.
     * 1 = a seed search is currently in progress and the remaining fields
     *     hold valid resume state. Cleared to 0 when the search concludes. */

    uint8_t enum_mode;
    /* Selects the seed enumeration strategy for the current search.
     * 0 = linear scan (reserved; not currently activated).
     * 1 = ring scan: seeds are visited in outward-expanding rings centred on
     *     ap_pred, alternating +radius and -radius each step. */

    /* ------------------------------------------------------------------ */
    /* Identity — used to detect stale state on resume                     */
    /* ------------------------------------------------------------------ */

    uint64_t bv_target;
    /* The BlockVector slot index (0-based) this search is trying to fill.
     * If the resume path finds that this differs from the requested slot,
     * the state is treated as stale and reinitialised. */

    SectionDataType focus;
    /* The section type being sought for bv_target (e.g. SECTION_TEXT,
     * SECTION_DYNAMIC). Together with bv_target, uniquely identifies the
     * logical request. A mismatch on resume triggers a fresh init. */

    /* ------------------------------------------------------------------ */
    /* AP window                                                            */
    /* ------------------------------------------------------------------ */

    uint64_t ap_pred;
    /* Predicted apparent-block number for bv_target, derived from the
     * nearest already-placed neighbour slot via linear extrapolation. Acts
     * as the centre of the initial search window and the ring scan origin.
     * Clamped to [ap_lo, ap_hi] after each window expansion. Also returned
     * to the caller as the suggested block_choice_start hint. */

    uint64_t ap_lo;
    uint64_t ap_hi;
    /* Current active search window in apparent-block space. Seeds are only
     * enumerated within [ap_lo, ap_hi]. The window starts narrow around
     * ap_pred and expands by window_expand_delta each time the ring
     * enumerator exhausts all candidates, until it reaches the cap. */

    uint64_t ap_cap_lo;
    uint64_t ap_cap_hi;
    /* Hard corridor boundaries that the search window may never exceed.
     * Derived from the global apparent-block range and any locality
     * constraints at initialisation time. Window expansion stops once
     * [ap_lo, ap_hi] reaches [ap_cap_lo, ap_cap_hi]. */

    uint32_t stage;
    /* Number of window expansions that have occurred so far during this
     * search. Starts at 0 and increments each time the ring enumerator
     * exhausts the current window and a larger window is adopted. Used
     * for diagnostics and to detect when the cap has been reached. */

    /* ------------------------------------------------------------------ */
    /* Ring enumerator state                                                */
    /* ------------------------------------------------------------------ */

    uint64_t radius;
    /* Current ring radius: the distance from ap_pred at which the next
     * seed candidate will be sampled. Starts at 0 (the predicted position
     * itself) and increases by 1 after both the +radius and -radius
     * positions have been visited. Reset to 0 on each window expansion. */

    uint8_t phase;
    /* Which side of the ring is visited next at the current radius.
     * 0 = positive side (ap_pred + radius) is next.
     * 1 = negative side (ap_pred - radius) is next.
     * Alternates each step so the enumerator fans out symmetrically. */

    /* ------------------------------------------------------------------ */
    /* Top-M retention table                                                */
    /* ------------------------------------------------------------------ */

    uint32_t top_count;
    /* Number of valid entries currently in the top[] table, in the range
     * [0, ELF_SEED_TOPM_MAX]. Entries are kept in descending score order;
     * the best seed is always at top[0]. */

    struct {
        uint64_t ap_seed;
        /* Apparent-block number of this seed candidate. This is the value
         * that will be committed as the placement for bv_target if this
         * entry is selected (i.e. if it remains at top[0] when the search
         * concludes). */

        double score;
        /* Composite placement score for this seed:
         *   avg_p * tail_p * length_confidence_factor
         * Higher is better. Used as the sort key for the top-M table and
         * compared against tau_place_main to decide whether the best seed
         * is strong enough to commit. */

        double avg_p;
        /* Mean per-step classifier probability over the preview run for
         * this seed. Reflects how well the blocks in the predicted run
         * match the expected section type on average. */

        double tail_p;
        /* Soft worst-case score for this seed's preview run: the mean of
         * the two lowest per-step probabilities observed (tail_k=2).
         * Penalises seeds whose runs contain weak outlier blocks even if
         * their average is acceptable. */

        uint32_t run_len;
        /* Number of steps completed in the preview run for this seed
         * before it hit a boundary, a low-probability stop, or the
         * maximum preview length. Shorter runs receive a scaled-down
         * length confidence factor in the score formula. */

        uint8_t flags;
        /* Bitmask of outcome flags from the preview run:
         *   bit 0 (0x01): boundary_hit — the preview run reached a
         *                 ground-truth section boundary within the
         *                 look-ahead distance, indicating a good length
         *                 match. Seeds with this bit set receive a
         *                 boundary floor boost to their length factor. */

    } top[ELF_SEED_TOPM_MAX];
    /* Sorted array of the best seeds seen so far, in descending score
     * order. Capacity is ELF_SEED_TOPM_MAX (default 16). When the table
     * is full, a new seed only displaces an existing entry if its score
     * is higher. top[0] holds the current best candidate. */

} ElfSeedSearchState;



/**
 * FileState — Persistent reassembly state for a single ELF candidate.
 *
 * Created during candidate initialization for fragmented reassembly and
 * persisted across reassembly calls via carve_put_state / carve_get_state.
 * It holds everything needed to resume reassembly after a checkpoint:
 * the ground-truth skeleton derived from the ELF headers, progress flags
 * tracking which major structural sections have been placed, and the full
 * cursor state for both in-flight seed searches and gallop passes.
 *
 * Skeleton (components[]):
 *   Built once by build_candidate_state_64/32 from the reconstructed 
 *   SHT and .shstrtab. Each FileComponent describes one contiguous
 *   region of the target file — its expected type (ELF header, PHT, SHT,
 *   .dynamic, .text, relocations, etc.), file offset, and size. This array
 *   is the ground truth that all subsequent block placement decisions are
 *   measured against. It functions as a roadmap for the reassembly effort, 
 *   and expected block geometry is derived from it during block scoring. 
 *   skeleton_initialized is set to true once it has been successfully populated.
 *
 * Placement flags (sht_placed … strings_placed):
 *   One boolean per major section type, set to true as each section is
 *   successfully committed to the BlockVector. Used to figure out what 
 *   sections are available for cross-validation and to gate the resume 
 *   path: if the skeleton plus the three anchor sections (SHT, PHT, SHSTRTAB) 
 *   are all in place,a resumed candidate skips re-initialisation.
 *
 * Scan cursor (elf_scan_*):
 *   Tracks the search state of whichever block vector position is in-progress 
 *   so it can be resumed on the next call. Two modes are encoded:
 *     - Seed-preview search: elf_scan_slot holds the BV slot, elf_scan_focus
 *       holds the section type, elf_scan_scanned holds the cumulative count
 *       of AP positions evaluated, and elf_scan_N holds the apparent-space
 *       size used for the exhaustion test.
 *     - Gallop resume: signalled by elf_scan_scanned == UINT64_MAX. In this
 *       mode elf_scan_slot holds the BV slot to resume and elf_scan_N holds
 *       a packed (dir, next_ap) pair produced by elf_pack_gallop_resume.
 *   The scan cursor is cleared (via elf_clear_scan_and_seed_state) whenever
 *   a search concludes or is invalidated.
 *
 * Failed-gallop guard (failed_gallop_*):
 *   Records the most recent gallop that produced no placements. Before
 *   launching a new gallop from the same (start_bv, dir) pair, the engine
 *   checks this guard and skips it to avoid repeating futile work.
 *   Cleared on any successful placement via elf_clear_failed_gallop.
 *
 * Seed search state (seed_state):
 *   The full enumerator and top-M retention state for the current seed
 *   search. Controls search, enumeration, and preview settings. 
 *   See ElfSeedSearchState for details.
 */
typedef struct {

    /* ------------------------------------------------------------------ */
    /* Skeleton                                                             */
    /* ------------------------------------------------------------------ */

    FileComponent *components;
    /* Array of FileComponent entries describing every expected region of
     * the target ELF file — ELF header, PHT, SHT, and each section —
     * in file-offset order. Derived from the SHT and PHT during skeleton
     * initialisation. Drives all block placement and coverage decisions.
     * Heap-allocated; freed by elf_free_carve_state. */

    size_t num_components;
    /* Number of valid entries in components[]. Zero until the skeleton
     * has been successfully built; checked alongside skeleton_initialized
     * before trusting the array contents. */

    bool skeleton_initialized;
    /* True once build_candidate_state_64/32 has successfully parsed the
     * SHT/PHT and populated components[]. Guards the resume fast-path:
     * a candidate with skeleton_initialized && sht_placed && pht_placed
     * && shstrtab_placed skips re-initialisation on re-entry. */

    /* ------------------------------------------------------------------ */
    /* Placement progress flags                                             */
    /* ------------------------------------------------------------------ */

    bool sht_placed;
    /* True once the Section Header Table block has been committed to the
     * BlockVector. Required (with pht_placed and shstrtab_placed) to
     * activate the skeleton resume fast-path. */

    bool pht_placed;
    /* True once the Program Header Table block has been committed to the
     * BlockVector. Required for the skeleton resume fast-path. */

    bool shstrtab_placed;
    /* True once the .shstrtab (section name string table) block has been
     * committed. Required for the skeleton resume fast-path. */

    bool dynamic_placed;
    /* True once the .dynamic section block has been committed. Used to
     * deprioritise or skip further DYNAMIC-focused search passes. */

    bool relocations_placed;
    /* True once all relocation section blocks have been committed. Used
     * to deprioritise further RELOCATION-focused search passes. */

    bool strings_placed;
    /* True once all string table section blocks have been committed. Used
     * to deprioritise further STRING-focused search passes. */

    /* ------------------------------------------------------------------ */
    /* Initial gallop                                                       */
    /* ------------------------------------------------------------------ */

    bool initial_gallop_done;
    /* True once the one-shot initial gallop pass has been executed for
     * this candidate. On first entry to the reassembly loop the engine
     * runs a greedy gallop outward from every already-placed block to
     * greedily extend runs; this flag ensures that pass runs exactly once
     * and is skipped on all subsequent re-entries. */

    /* ------------------------------------------------------------------ */
    /* Scan cursor                                                          */
    /* ------------------------------------------------------------------ */

    uint64_t elf_scan_slot;
    /* BV slot index currently being searched or resumed. Set to UINT64_MAX
     * when no search is in flight. In gallop-resume mode this identifies
     * which slot the interrupted gallop was trying to extend. */

    uint64_t elf_scan_scanned;
    /* Cumulative number of apparent-block positions evaluated so far for
     * elf_scan_slot during a seed-preview search. Incremented each ring
     * step. The special sentinel value UINT64_MAX signals gallop-resume
     * mode: the scan cursor encodes a packed gallop continuation rather
     * than a seed search in progress. */

    uint64_t elf_scan_N;
    /* In seed-preview mode: the apparent-space size (last_apparent) used
     * as the exhaustion threshold — when elf_scan_scanned reaches this
     * value the entire apparent space has been evaluated and the search
     * is considered exhausted.
     * In gallop-resume mode (elf_scan_scanned == UINT64_MAX): a packed
     * (dir, next_ap) pair produced by elf_pack_gallop_resume, consumed
     * by elf_unpack_gallop_resume to restart the gallop. */

    SectionDataType elf_scan_focus;
    /* The section type being sought during the current seed-preview search
     * (e.g. SECTION_TEXT, SECTION_DYNAMIC). Used on resume to verify the
     * in-flight search still matches the requested focus before continuing.
     * Set to (SectionDataType)-1 when no seed search is active or in
     * gallop-resume mode. */

    /* ------------------------------------------------------------------ */
    /* Failed-gallop guard                                                  */
    /* ------------------------------------------------------------------ */

    bool failed_gallop_valid;
    /* True when failed_gallop_start_bv and failed_gallop_dir hold the
     * recorded coordinates of a gallop that produced no placements.
     * Cleared on any successful placement via elf_clear_failed_gallop. */

    uint64_t failed_gallop_start_bv;
    /* BV slot from which the most recently failed gallop was launched.
     * Only meaningful when failed_gallop_valid is true. */

    int32_t failed_gallop_dir;
    /* Direction (+1 or -1) of the most recently failed gallop.
     * Only meaningful when failed_gallop_valid is true. */

    /* ------------------------------------------------------------------ */
    /* Seed search state                                                    */
    /* ------------------------------------------------------------------ */

    ElfSeedSearchState seed_state;
    /* Full enumerator and top-M retention state for the seed-preview
     * search currently in flight. Embedded directly (not a pointer) so
     * it is serialised and copied atomically with the rest of FileState.
     * See ElfSeedSearchState for field-level documentation. */

} FileState;


