static inline size_t carve_fp_len_bytes(size_t want)
{
    if (want > CARVE_HASH_KEY_SIZE) want = CARVE_HASH_KEY_SIZE;
    return want;
}

static inline void print_hex_fingerprint(FILE *out, const char *key_bytes, size_t nbytes)
{
    const unsigned char *b = (const unsigned char *)key_bytes;
    for (size_t i = 0; i < nbytes; ++i) {
        /* always printable */
        fprintf(out, "%02x", (unsigned)b[i]);
    }
}


/* Print a fingerprint prefix; prefix_len is in BYTES (not chars).
 * Example: prefix_len=12 prints 24 hex chars, always printable.
 */
static inline void print_carvehashkey_prefix(FILE *out,
                                             const char carvehashkey[CARVE_HASH_KEY_SIZE],
                                             size_t prefix_len)
{
    if (!out) out = stderr;
    if (!carvehashkey) { fputs("(null)", out); return; }

    const size_t n = carve_fp_len_bytes(prefix_len);
    print_hex_fingerprint(out, carvehashkey, n);

    if (n < CARVE_HASH_KEY_SIZE) fputs("…", out);
}


/* Format a stable printable hex fingerprint for logs (prefix of carvehashkey). */
static inline const char *carvehashkey_fp_hex(const char *carvehashkey,
                                              char *dst,
                                              size_t dstsz)
{
    if (!dst || dstsz == 0) return "(fp-buf-null)";
    dst[0] = '\0';

    if (!carvehashkey) {
        snprintf(dst, dstsz, "(null)");
        return dst;
    }

    const size_t n = carve_fp_len_bytes(CARVE_HASH_FINGERPRINT_BYTES);
    size_t o = 0;
    for (size_t i = 0; i < n; ++i) {
        if (o + 2 >= dstsz) break;
        int w = snprintf(dst + o, dstsz - o, "%02x",
                         (unsigned)(unsigned char)carvehashkey[i]);
        if (w <= 0) break;
        o += (size_t)w;
    }
    dst[dstsz - 1] = '\0';

    if (n < CARVE_HASH_KEY_SIZE) {
        if (strlen(dst) + 4 < dstsz) strcat(dst, "…");
    }
    return dst;
}


/***************************************************************/
/*         SCALPEL BLOCK STATE API FUNCTION DEFINITIONS        */
/***************************************************************/

// serialize or deserialize block state to a file
static inline bool elf_serialize_block_state(void **state, FILE *fp, StateSerialization mode) {

  BlockState **s = (BlockState **)state;

  size_t (*fb)(void *ptr, size_t size, size_t nitems, FILE *stream) =
    mode == SERIALIZE ?
    (size_t (*)(void *ptr, size_t size, size_t nitems, FILE *stream))fwrite :
    (size_t (*)(void *ptr, size_t size, size_t nitems, FILE *stream))fread;

  if (mode == DESERIALIZE) {
    *s = malloc(sizeof(BlockState));
    check_memory_allocation(*s, __LINE__, __FILE__, "s");
    (*s)->components = NULL;
    (*s)->num_components = 0;
  }

  // num_components
  if (fb(&(*s)->num_components, sizeof((*s)->num_components), 1, fp) != 1) {
    perror("elf num_components");
    handle_error(SCALPEL_ERROR_CHECKPOINT, NULL, __LINE__, __FILE__);
  }

  // components
  if (mode == DESERIALIZE) {
    (*s)->components = malloc((*s)->num_components * sizeof(BlockComponent));
    check_memory_allocation((*s)->components, __LINE__, __FILE__, "components");
  }

  if (fb((*s)->components, sizeof(BlockComponent), (*s)->num_components, fp) != (*s)->num_components) {
    perror("elf components");
    handle_error(SCALPEL_ERROR_CHECKPOINT, NULL, __LINE__, __FILE__);
  }

  return true;
}

// clone ELF block state
static inline void *elf_clone_block_state(const void *srcstate) {

  const BlockState *s = (const BlockState *)srcstate;
  BlockState *d = malloc(sizeof(BlockState));
  check_memory_allocation(d, __LINE__, __FILE__, "d");
  d->num_components = s->num_components;
  d->components = malloc(d->num_components * sizeof(BlockComponent));
  check_memory_allocation(d->components, __LINE__, __FILE__, "d->components");
  memcpy(d->components, s->components, d->num_components * sizeof(BlockComponent));

  return d;
}

// free ELF block state
static inline void elf_free_block_state(void **state) {
    if (!state) return;

    BlockState **s = (BlockState **)state;
    if (!*s) return;

    free((*s)->components);
    free(*s);
    *s = NULL;
}

// compare two states associated with ELF blocks
static inline bool elf_compare_block_state(const void *state1, const void *state2) {

  const BlockState *s1 = (const BlockState *)state1;
  const BlockState *s2 = (const BlockState *)state2;

  if (s1->num_components != s2->num_components) {
    return false;
  }

  return memcmp(s1->components, s2->components, s1->num_components * sizeof(BlockComponent)) == 0;
}

// display a representation of ELF block state
static inline void elf_print_block_state(const void *state) {

  const BlockState *s = (const BlockState *)state;

  if (! s) {
    fprintf(stdout, "NULL\n");
  }
  else {
    fprintf(stdout, "{num_components=%zu}\n", s->num_components);
  }
}


/***************************************************************/
/*         SCALPEL CARVE STATE API FUNCTION DEFINITIONS        */
/***************************************************************/

static inline bool elf_serialize_carve_state(void **state, FILE *fp, StateSerialization mode)
{
  FileState **s = (FileState **)state;

  size_t (*fb)(void *ptr, size_t size, size_t nitems, FILE *stream) =
    mode == SERIALIZE ?
    (size_t (*)(void *ptr, size_t size, size_t nitems, FILE *stream))fwrite :
    (size_t (*)(void *ptr, size_t size, size_t nitems, FILE *stream))fread;

  if (mode == DESERIALIZE) {
    *s = malloc(sizeof(FileState));
    check_memory_allocation(*s, __LINE__, __FILE__, "s");
    (*s)->components = NULL;
    (*s)->num_components = 0;
    (*s)->sht_placed = false;
    (*s)->pht_placed = false;
    (*s)->shstrtab_placed = false;
    (*s)->dynamic_placed = false;
    (*s)->relocations_placed = false;
    (*s)->strings_placed = false;
    (*s)->skeleton_initialized = false;
    (*s)->initial_gallop_done = false;
    (*s)->elf_scan_slot = UINT64_MAX;
    (*s)->elf_scan_scanned = 0;
    (*s)->elf_scan_N = 0;
    (*s)->elf_scan_focus = (SectionDataType)-1;

    (*s)->failed_gallop_valid = false;
    (*s)->failed_gallop_start_bv = UINT64_MAX;
    (*s)->failed_gallop_dir = 0;

    memset(&(*s)->seed_state, 0, sizeof((*s)->seed_state));
    (*s)->seed_state.active = 0;
  }

  if (fb(&(*s)->num_components, sizeof((*s)->num_components), 1, fp) != 1) {
    perror("elf num_components");
    handle_error(SCALPEL_ERROR_CHECKPOINT, NULL, __LINE__, __FILE__);
  }

  if (mode == DESERIALIZE) {
    (*s)->components = malloc((*s)->num_components * sizeof(FileComponent));
    check_memory_allocation((*s)->components, __LINE__, __FILE__, "components");
  }

  if (fb((*s)->components, sizeof(FileComponent), (*s)->num_components, fp) != (*s)->num_components) {
    perror("elf components");
    handle_error(SCALPEL_ERROR_CHECKPOINT, NULL, __LINE__, __FILE__);
  }

  if (fb(&(*s)->sht_placed, sizeof((*s)->sht_placed), 1, fp) != 1) {
    perror("elf sht_placed");
    handle_error(SCALPEL_ERROR_CHECKPOINT, NULL, __LINE__, __FILE__);
  }

  if (fb(&(*s)->pht_placed, sizeof((*s)->pht_placed), 1, fp) != 1) {
    perror("elf pht_placed");
    handle_error(SCALPEL_ERROR_CHECKPOINT, NULL, __LINE__, __FILE__);
  }

  if (fb(&(*s)->shstrtab_placed, sizeof((*s)->shstrtab_placed), 1, fp) != 1) {
    perror("elf shstrtab_placed");
    handle_error(SCALPEL_ERROR_CHECKPOINT, NULL, __LINE__, __FILE__);
  }

  if (fb(&(*s)->dynamic_placed, sizeof((*s)->dynamic_placed), 1, fp) != 1) {
    perror("elf dynamic_placed");
    handle_error(SCALPEL_ERROR_CHECKPOINT, NULL, __LINE__, __FILE__);
  }

  if (fb(&(*s)->relocations_placed, sizeof((*s)->relocations_placed), 1, fp) != 1) {
    perror("elf relocations_placed");
    handle_error(SCALPEL_ERROR_CHECKPOINT, NULL, __LINE__, __FILE__);
  }

  if (fb(&(*s)->strings_placed, sizeof((*s)->strings_placed), 1, fp) != 1) {
    perror("elf strings_placed");
    handle_error(SCALPEL_ERROR_CHECKPOINT, NULL, __LINE__, __FILE__);
  }

  if (fb(&(*s)->skeleton_initialized, sizeof((*s)->skeleton_initialized), 1, fp) != 1) {
    perror("elf skeleton_initialized");
    handle_error(SCALPEL_ERROR_CHECKPOINT, NULL, __LINE__, __FILE__);
  }

  if (fb(&(*s)->initial_gallop_done, sizeof((*s)->initial_gallop_done), 1, fp) != 1) {
    perror("elf initial_gallop_done");
    handle_error(SCALPEL_ERROR_CHECKPOINT, NULL, __LINE__, __FILE__);
  }

  if (fb(&(*s)->elf_scan_slot, sizeof((*s)->elf_scan_slot), 1, fp) != 1) {
    perror("elf elf_scan_slot");
    handle_error(SCALPEL_ERROR_CHECKPOINT, NULL, __LINE__, __FILE__);
  }
  if (fb(&(*s)->elf_scan_scanned, sizeof((*s)->elf_scan_scanned), 1, fp) != 1) {
    perror("elf elf_scan_scanned");
    handle_error(SCALPEL_ERROR_CHECKPOINT, NULL, __LINE__, __FILE__);
  }
  if (fb(&(*s)->elf_scan_N, sizeof((*s)->elf_scan_N), 1, fp) != 1) {
    perror("elf elf_scan_N");
    handle_error(SCALPEL_ERROR_CHECKPOINT, NULL, __LINE__, __FILE__);
  }
  if (fb(&(*s)->elf_scan_focus, sizeof((*s)->elf_scan_focus), 1, fp) != 1) {
    perror("elf elf_scan_focus");
    handle_error(SCALPEL_ERROR_CHECKPOINT, NULL, __LINE__, __FILE__);
  }

  if (fb(&(*s)->failed_gallop_valid, sizeof((*s)->failed_gallop_valid), 1, fp) != 1) {
    perror("elf failed_gallop_valid");
    handle_error(SCALPEL_ERROR_CHECKPOINT, NULL, __LINE__, __FILE__);
  }
  if (fb(&(*s)->failed_gallop_start_bv, sizeof((*s)->failed_gallop_start_bv), 1, fp) != 1) {
    perror("elf failed_gallop_start_bv");
    handle_error(SCALPEL_ERROR_CHECKPOINT, NULL, __LINE__, __FILE__);
  }
  if (fb(&(*s)->failed_gallop_dir, sizeof((*s)->failed_gallop_dir), 1, fp) != 1) {
    perror("elf failed_gallop_dir");
    handle_error(SCALPEL_ERROR_CHECKPOINT, NULL, __LINE__, __FILE__);
  }

  if (fb(&(*s)->seed_state, sizeof((*s)->seed_state), 1, fp) != 1) {
    perror("elf seed_state");
    handle_error(SCALPEL_ERROR_CHECKPOINT, NULL, __LINE__, __FILE__);
  }

  return true;
}


static inline void *elf_clone_carve_state(const void *srcstate)
{
  const FileState *s = (const FileState *)srcstate;
  FileState *d = malloc(sizeof(FileState));
  check_memory_allocation(d, __LINE__, __FILE__, "d");

  d->num_components = s->num_components;
  d->components = malloc(d->num_components * sizeof(FileComponent));
  check_memory_allocation(d->components, __LINE__, __FILE__, "d->components");
  memcpy(d->components, s->components, d->num_components * sizeof(FileComponent));

  d->sht_placed = s->sht_placed;
  d->pht_placed = s->pht_placed;
  d->shstrtab_placed = s->shstrtab_placed;
  d->dynamic_placed = s->dynamic_placed;
  d->relocations_placed = s->relocations_placed;
  d->strings_placed = s->strings_placed;
  d->skeleton_initialized = s->skeleton_initialized;
  d->initial_gallop_done = s->initial_gallop_done;

  d->elf_scan_slot = s->elf_scan_slot;
  d->elf_scan_scanned = s->elf_scan_scanned;
  d->elf_scan_N = s->elf_scan_N;
  d->elf_scan_focus = s->elf_scan_focus;

  d->failed_gallop_valid = s->failed_gallop_valid;
  d->failed_gallop_start_bv = s->failed_gallop_start_bv;
  d->failed_gallop_dir = s->failed_gallop_dir;

  d->seed_state = s->seed_state;

  return d;
}


static inline void elf_free_carve_state(void **state)
{
  FileState **s = (FileState **)state;
  free((*s)->components);
  free(*s);
  *s = NULL;
}


static inline bool elf_compare_carve_state(const void *state1, const void *state2)
{
  const FileState *s1 = (const FileState *)state1;
  const FileState *s2 = (const FileState *)state2;

  // AFTER
  if (s1->num_components != s2->num_components) {
    return false;
  }

  if (memcmp(s1->components, s2->components,
             s1->num_components * sizeof(FileComponent)) != 0) {
    return false;
  }

  if (s1->sht_placed != s2->sht_placed ||
      s1->pht_placed != s2->pht_placed ||
      s1->shstrtab_placed != s2->shstrtab_placed ||
      s1->dynamic_placed != s2->dynamic_placed ||
      s1->relocations_placed != s2->relocations_placed ||
      s1->strings_placed != s2->strings_placed ||
      s1->skeleton_initialized != s2->skeleton_initialized ||
      s1->initial_gallop_done != s2->initial_gallop_done) {
    return false;
  }

  if (s1->elf_scan_slot != s2->elf_scan_slot ||
      s1->elf_scan_scanned != s2->elf_scan_scanned ||
      s1->elf_scan_N != s2->elf_scan_N ||
      s1->elf_scan_focus != s2->elf_scan_focus) {
    return false;
  }

  if (s1->failed_gallop_valid != s2->failed_gallop_valid ||
      s1->failed_gallop_start_bv != s2->failed_gallop_start_bv ||
      s1->failed_gallop_dir != s2->failed_gallop_dir) {
    return false;
  }

  if (memcmp(&s1->seed_state, &s2->seed_state, sizeof(s1->seed_state)) != 0) {
    return false;
  }

  return true;
}


static inline void elf_print_carve_state(const void *state)
{
  const FileState *s = (const FileState *)state;

  if (!s) {
    fprintf(stdout, "NULL\n");
  } else {
    fprintf(stdout,
      "{num_components=%zu, "
      "sht_placed=%d, pht_placed=%d, shstrtab_placed=%d, "
      "dynamic_placed=%d, relocations_placed=%d, strings_placed=%d, "
      "skeleton_initialized=%d, initial_gallop_done=%d, "
      "scan={slot=%" PRIu64 ", scanned=%" PRIu64 ", N=%" PRIu64 ", focus=%d}, "
      "failed_gallop={valid=%d, start_bv=%" PRIu64 ", dir=%d}, "
      "seed={active=%u, bv_target=%" PRIu64 ", focus=%d, ap_pred=%" PRIu64 ", lo=%" PRIu64 ", hi=%" PRIu64 ", stage=%u, top=%u}"
      "}\n",
      s->num_components,
      s->sht_placed,
      s->pht_placed,
      s->shstrtab_placed,
      s->dynamic_placed,
      s->relocations_placed,
      s->strings_placed,
      s->skeleton_initialized,
      s->initial_gallop_done,
      s->elf_scan_slot, s->elf_scan_scanned, s->elf_scan_N, (int)s->elf_scan_focus,
      (int)s->failed_gallop_valid,
      s->failed_gallop_start_bv,
      (int)s->failed_gallop_dir,
      (unsigned)s->seed_state.active,
      (uint64_t)s->seed_state.bv_target,
      (int)s->seed_state.focus,
      (uint64_t)s->seed_state.ap_pred,
      (uint64_t)s->seed_state.ap_lo,
      (uint64_t)s->seed_state.ap_hi,
      (unsigned)s->seed_state.stage,
      (unsigned)s->seed_state.top_count
    );
  }
}



